class Solution {
  public long sumOfAncestors(int n, int[][] edges, int[] nums) {
    int MAX = 100_001;
    int[] spf = new int[MAX];
    for (int i = 2; i < MAX; i++) {
      if (spf[i] != 0) continue;
      for (int j = i; j < MAX; j += i) if (spf[j] == 0) spf[j] = i;
    }
    int[] kernel = new int[n];
    for (int i = 0; i < n; i++) {
      int x = nums[i], k = 1;
      while (x > 1) {
        int p = spf[x], c = 0;
        while (x % p == 0) {
          x /= p;
          c++;
        }
        if ((c & 1) == 1) k *= p;
      }
      kernel[i] = k;
    }
    int[] start = new int[n + 1];
    for (int[] e : edges) {
      start[e[0] + 1]++;
      start[e[1] + 1]++;
    }
    for (int i = 0; i < n; i++) start[i + 1] += start[i];
    int[] fill = new int[n], to = new int[2 * (n - 1)];
    for (int[] e : edges) {
      to[start[e[0]] + fill[e[0]]++] = e[1];
      to[start[e[1]] + fill[e[1]]++] = e[0];
    }
    int[] cnt = new int[MAX], stack = new int[n], ptr = new int[n], par = new int[n];
    int sp = 0;
    long total = 0;
    stack[sp++] = 0;
    par[0] = -1;
    ptr[0] = start[0];
    cnt[kernel[0]]++;
    while (sp > 0) {
      int u = stack[sp - 1];
      if (ptr[u] < start[u + 1]) {
        int v = to[ptr[u]++];
        if (v == par[u]) continue;
        par[v] = u;
        ptr[v] = start[v];
        total += cnt[kernel[v]];
        cnt[kernel[v]]++;
        stack[sp++] = v;
      } else {
        cnt[kernel[u]]--;
        sp--;
      }
    }
    return total;
  }
}
